from pathlib import Path
from PIL import Image
import json
b=Path('assets/player-integrated/source-art/wholecast-v17');refs=b/'action-references';refs.mkdir(exist_ok=True);(b/'motion').mkdir(exist_ok=True)
m=json.loads((b/'drawing-manifest.json').read_text(encoding='utf8'));jobs=[]
for c in m['characters']:
 name=c['character'];src=Image.open(b/(name+'-native-8views.png')).convert('RGBA')
 for d in ['S','SE','E','NE','N']:
  di=m['directionOrder'].index(d);im=src.crop((di%4*112,di//4*112,di%4*112+112,di//4*112+112));im.resize((448,448),Image.Resampling.NEAREST).save(refs/f'{name}-{d}-master.png')
  for action in ['walk','run','attack' if name=='swordsman' else 'cast']:
   n=12 if action in ['attack','cast'] else 8;rows=n//4;t=Image.new('RGBA',(448,112*rows))
   for i in range(n):t.paste(im,(i%4*112,i//4*112))
   t.resize((1792,448*rows),Image.Resampling.NEAREST).save(refs/f'{name}-{d}-{action}-template.png')
   poses={'walk':'8 sequential gentle walking phases: near-leg forward contact, near-leg down, passing, rising; far-leg forward contact, far-leg down, passing, rising. In the second half the NEAR leg is visibly behind while the FAR leg is in front. Boots lift and weight shifts gently. Head/torso stay upright, only one logical pixel bob.','run':'8 sequential running phases with clearly alternating legs and bent knees: near-leg contact, compression, passing/push off, brief flight; far-leg contact, compression, passing/push off, brief flight. Slight constant whole torso lean from hips, real leg motion. Head stays same width/height, boots lift.','attack':'12 sequential decisive TWO-HANDED overhead sword chop phases:0 exact relaxed master;1 hand joins grip;2 lift sword in front;3 hands above forehead;4 high overhead anticipation;5 blade behind crown;6 accelerating downstroke;7 impact downward in front;8 low follow-through;9 recover;10 return;11 exact master stance. Both hands visibly clasp the SAME hilt during chop, sword follows arms as a rigid solid. Continuous clear single downward chop.','cast':'12 sequential staff spellcasting phases:0 exact master stance;1 settle;2 free hand approaches chest;3 gather energy gesture;4 staff slightly lifts;5 free arm extends;6 staff points forward and free palm releases;7 hold release;8 release follow-through;9 lower arm;10 return;11 exact master. Gripping hand always encloses staff shaft. Staff remains rigid and attached. Draw the body/gesture only; game supplies spell effects.'}[action]
   prompt=f'Edit target Image1, a {n}-pose sprite template of one approved COMPLETE {name}. Image2 is the exact approved character master at integer 4x zoom. Make a {action.upper()} animation in {d} facing direction, same direction in every frame. Keep strict4columns x{rows}rows order left-to-right then down, same canvas aspect ratio and exact regular cell centers. {poses} Preserve master identity, hair silhouette, face/chin, head size, shoulder width, torso length, waist and limb thickness. Body crown-to-sole75 logical pixels, head width about23 logical pixels; all parts retain master proportions. Preserve master clean RPG pixel art cluster sizes and discrete material shades. Strong crisp stepped pixel edges and clean readable shapes. Full hair/head is repeated faithfully through movement. Clothing and exactly one '+('silver sword' if name=='swordsman' else 'teal crystal wooden staff')+' are painted into each COMPLETE actor. One continuous integrated character image per frame. Weapon grip is enclosed by fingers, no floating weapon or detached parts. Fixed camera/scale/lighting/palette across all frames; feet ground line and body root remain on the same source row grid. Allow natural bent legs or raised arms without resizing any body part. Transparent background with generous margins for weapon arcs. No text, no blur, no soft gradients, no painted microtexture, no motion trails, no ground circles, no props, no extra characters, no separate equipment.'
   stem=f'{name}-{action}-{d}';(b/'motion'/f'{stem}.prompt.txt').write_text(prompt,encoding='utf8');jobs.append({'name':stem,'character':name,'direction':d,'action':action,'frames':n,'template':(refs/f'{name}-{d}-{action}-template.png').as_posix(),'master':(refs/f'{name}-{d}-master.png').as_posix(),'prompt':prompt,'approved':False})
(b/'motion-jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
print('Prepared',len(jobs),'complete-character direction/action jobs')
